def fill_wave(grid, marker, bg, fire_mode, solid_mode, parity):
    h,wd=len(grid),len(grid[0])
    comps,comp_of=analyze(grid,marker,bg)
    out=[r[:] for r in grid]
    for i in range(h):
        mc=max((j for j,v in enumerate(grid[i]) if v==marker),default=-1)
        if mc<0 or mc==wd-1 or (i,mc) not in comp_of: continue
        comp=comps[comp_of[(i,mc)]]
        mr=max(j for _,j in comp)
        fire=False
        if fire_mode=='eq': fire=(mc==mr)
        elif fire_mode=='eq_or_prev':
            fire=(mc==mr)
            if not fire and mc==mr-1:
                rstar=min(r for r,c2 in comp if c2==mr)
                if i==rstar+1 and grid[rstar][mr-1]==bg: fire=True
        elif fire_mode=='ge': fire=(mc>=mr-1)
        if not fire: continue
        solid=None
        if solid_mode=='left_above':
            solid=(mc>0 and grid[i][mc-1]==marker) or (i>0 and grid[i-1][mc]==marker)
        elif solid_mode=='run':
            k=mc
            while k>0 and grid[i][k-1]==marker: k-=1
            solid=(mc-k+1)>1
        elif solid_mode=='always': solid=True
